func TestKeyMapStubBenchModeZeroAlloc(t *testing.T) {
	s := genericstest.NewKeyMapStub[string, int](nil, genericstest.KeyMapStubBenchMode[string, int]())
	s.OnGet.Returns(*new(int), nil)
	s.OnSet.Returns(nil)

	t.Run("Get", func(t *testing.T) {
		allocs := testing.AllocsPerRun(100, func() {
			_, _ = s.Get(t.Context(), *new(string))
		})
		testkit.Equal(t, allocs, 0.0, "Get: BenchMode dispatch must allocate zero per call")
	})

	t.Run("Set", func(t *testing.T) {
		allocs := testing.AllocsPerRun(100, func() {
			_ = s.Set(t.Context(), *new(string), *new(int))
		})
		testkit.Equal(t, allocs, 0.0, "Set: BenchMode dispatch must allocate zero per call")
	})
}
